const now = new Date();
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0));
const ymd = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    start_date: ymd(start),
    end_date: ymd(end),
  },
}];

function collect(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  if (items.length === 1 && Array.isArray(items[0])) return items[0];
  return items.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
}

const period = $('Prepare Last Month').first().json;
const groups = collect('Get Connector Groups');

if (!groups.length) {
  return [{
    json: {
      _empty: true,
      start_date: period.start_date,
      end_date: period.end_date,
      message: 'No connector groups found.',
    },
  }];
}

return groups.map((g) => ({
  json: {
    start_date: period.start_date,
    end_date: period.end_date,
    connector_group_id: g.id,
    connector_group_name: g.display_name || g.name || '',
  },
}));

const group = $('Expand Groups').item.json;

if (group._empty) {
  return [{
    json: {
      period: {
        start_date: group.start_date,
        end_date: group.end_date,
      },
      connector_group_count: 0,
      invoice_count: 0,
      groups: [],
      note: group.message,
    },
  }];
}

const response = $input.first().json;
const invoices = Array.isArray(response.invoices)
  ? response.invoices
  : Array.isArray(response)
    ? response
    : [];

// Deduplicate when the same invoice appears under multiple file formats.
const seen = new Set();
let invoiceCount = 0;
for (const inv of invoices) {
  const key = [inv.credential_id, inv.invoice_number, inv.invoice_date].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  invoiceCount += 1;
}

return [{
  json: {
    start_date: group.start_date,
    end_date: group.end_date,
    connector_group_id: group.connector_group_id,
    connector_group_name: group.connector_group_name,
    invoice_count: invoiceCount,
  },
}];

const rows = $input.all().map((i) => i.json);

if (rows.length === 1 && rows[0].groups) {
  return [{ json: rows[0] }];
}

const period = rows[0] || {};
const groups = rows
  .map((r) => ({
    connector_group_id: r.connector_group_id,
    connector_group_name: r.connector_group_name,
    invoice_count: r.invoice_count || 0,
  }))
  .sort((a, b) => b.invoice_count - a.invoice_count);

const invoiceCount = groups.reduce((sum, g) => sum + g.invoice_count, 0);

return [{
  json: {
    period: {
      start_date: period.start_date,
      end_date: period.end_date,
    },
    connector_group_count: groups.length,
    invoice_count: invoiceCount,
    groups,
  },
}];
